.aff-hero{background:#182820;color:#fff;overflow:hidden}.aff-hero-inner{min-height:650px;display:grid;grid-template-columns:1.1fr .9fr;gap:34px;align-items:center}.aff-copy{position:relative;z-index:2;padding:80px 0}.aff-copy h1{font:400 clamp(52px,6.9vw,104px)/1.03 Georgia,serif;letter-spacing:-.05em;max-width:800px;margin:0 0 24px}.aff-copy h1 em{color:#e0c79a}.aff-copy>p:not(.overline):not(.aff-note){color:#d6e1d8;max-width:520px;font-size:17px;line-height:1.82;margin:0 0 32px}.aff-note{font-size:12px;color:#aebcaf;margin-top:26px;max-width:480px}.aff-hero-scene{position:relative;height:570px;display:grid;place-items:center;isolation:isolate}.aff-orbit{width:460px;height:460px;border:1px solid #e0c99b44;border-radius:50%;position:absolute;box-shadow:0 0 0 55px #dabd9010}.aff-stage-strap{position:absolute;height:390px;width:135px;background:linear-gradient(90deg,#354238,#b0b6a5 25%,#4a5f52 52%,#d7d9c3 76%,#324a39);transform:rotate(-18deg);border-radius:19px;box-shadow:18px 26px 25px #07110a77}.aff-stage-dial{position:relative;width:238px;height:238px;border:13px solid #d5bd8b;border-radius:50%;background:radial-gradient(circle at 32% 29%,#497f6a,#0d271a 72%);transform:rotate(-18deg);box-shadow:0 0 0 4px #8e7551,20px 29px 28px #0008}.aff-stage-dial:before,.aff-stage-dial:after{content:"";position:absolute;bottom:50%;left:50%;width:5px;background:#e9d0a5;transform-origin:bottom center;border-radius:4px}.aff-stage-dial:before{height:66px;transform:rotate(35deg)}.aff-stage-dial:after{height:87px;transform:rotate(-105deg)}.aff-stage-dial span{position:absolute;top:calc(50% - 6px);left:calc(50% - 6px);width:12px;height:12px;border-radius:50%;background:#f0d69f;z-index:1}.aff-hero-legend{position:absolute;bottom:35px;right:0;color:#c5b998;letter-spacing:.21em;font-size:10px}.aff-tiers{background:#ede9e0}.aff-tier-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:#d9d2c4}.aff-tier-grid>a{background:#f6f2ea;min-height:185px;padding:37px 29px;text-decoration:none;display:flex;flex-direction:column}.aff-tier-grid>a:hover{background:#eae2d1}.aff-tier-grid span{font-size:10px;letter-spacing:.18em;color:#97774a;text-transform:uppercase}.aff-tier-grid strong{font:400 37px Georgia,serif;margin-top:12px}.aff-tier-grid small{font-size:12px;color:#68756a;margin-top:7px}.aff-selection{padding:94px 0 112px;background:#fcfaf6}.aff-heading{display:grid;grid-template-columns:1.3fr .7fr;align-items:end;gap:55px;margin-bottom:28px}.aff-heading>p{max-width:470px;color:#5e6a61;line-height:1.77}.aff-disclosure{border-left:4px solid #b39a71;background:#f3eee5;padding:16px 21px;margin-bottom:31px;color:#405447}.aff-disclosure strong{font-size:13px}.aff-disclosure p{font-size:12px;line-height:1.75;margin:6px 0 0}.aff-tools{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap;margin-top:28px}.aff-tabs{display:flex;flex-wrap:wrap;gap:8px}.aff-tabs button{background:#fff;border:1px solid #cfc5b4;color:#273d2f;font:650 12px system-ui;padding:12px 14px;cursor:pointer}.aff-tabs button[aria-pressed=true]{background:#1c3727;color:#fff;border-color:#1c3727}.aff-query input{padding:12px 14px;border:1px solid #d0c7b8;background:white;min-width:min(300px,85vw);font-size:13px}.aff-result{color:#718075;font-size:13px;margin:20px 0}.aff-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.aff-card{min-width:0;background:#fff;border:1px solid #e4ded3;overflow:hidden;display:flex;flex-direction:column}.aff-illustration{height:235px;display:grid;place-items:center;background:linear-gradient(135deg,#eae7df,#d5dbd1);position:relative;isolation:isolate}.aff-illustration[data-tone=black]{background:linear-gradient(140deg,#506155,#202d2b)}.aff-illustration[data-tone=blue]{background:linear-gradient(140deg,#7c9dab,#21374b)}.aff-illustration[data-tone=green]{background:linear-gradient(140deg,#4d806e,#1a372a)}.aff-illustration[data-tone=turquoise]{background:linear-gradient(140deg,#a0ccc1,#446c73)}.aff-illustration[data-tone=ivory]{background:linear-gradient(140deg,#edddba,#adb19d)}.aff-illustration[data-tone=transparent]{background:linear-gradient(135deg,#d3e8e0,#819baa)}.aff-illustration[data-tone=silver]{background:linear-gradient(135deg,#d9d9d3,#9caba6)}.aff-illustration:before{content:'';position:absolute;width:184px;height:184px;border:1px solid #ffffff55;border-radius:50%}.aff-band{position:absolute;height:204px;width:65px;background:linear-gradient(90deg,#65736b,#cbd3cd 23%,#5c7064 51%,#d8ded0 75%,#51685a);transform:rotate(-17deg);border-radius:14px;filter:drop-shadow(8px 11px 8px #0004)}.aff-case{height:128px;width:128px;border:8px solid #dbccaa;border-radius:50%;background:radial-gradient(circle at 30% 22%,#91b5a8,#1b4a3a 76%);box-shadow:0 0 0 3px #8d836d,10px 13px 17px #0005;transform:rotate(-17deg);position:relative}.aff-illustration[data-tone=black] .aff-case{background:radial-gradient(circle at 30% 20%,#5d6c65,#131b19 75%)}.aff-illustration[data-tone=blue] .aff-case{background:radial-gradient(circle at 30% 20%,#9ec3cd,#193e65 75%)}.aff-illustration[data-tone=turquoise] .aff-case{background:radial-gradient(circle at 30% 20%,#c6ede0,#358798 75%)}.aff-illustration[data-tone=ivory] .aff-case{background:radial-gradient(circle at 30% 20%,#fff3d8,#a7a28a 75%)}.aff-illustration[data-tone=transparent] .aff-case{background:radial-gradient(circle at 30% 20%,#d0f3ee99,#779fa088 75%)}.aff-illustration[data-tone=silver] .aff-case{background:radial-gradient(circle at 30% 20%,#ecece4,#879a9c 75%)}.aff-illustration[data-tone=green] .aff-case{background:radial-gradient(circle at 30% 20%,#67a593,#134834 75%)}.aff-case:before,.aff-case:after{content:'';position:absolute;left:50%;bottom:50%;width:3px;background:#f9e9c8;transform-origin:bottom center}.aff-case:before{height:36px;transform:rotate(41deg)}.aff-case:after{height:48px;transform:rotate(-105deg)}.aff-case span{position:absolute;left:calc(50% - 4px);top:calc(50% - 4px);width:8px;height:8px;background:#f0d3a6;border-radius:50%}.aff-art-label{position:absolute;bottom:11px;left:12px;font-size:9px;color:#263b2e;background:#ffffffe0;padding:5px 7px;letter-spacing:.08em}.aff-card-body{padding:23px;display:flex;flex-direction:column;flex:1}.aff-card-brand{font-size:10px;font-weight:700;color:#9c7a4a;letter-spacing:.17em;text-transform:uppercase;margin:0 0 9px}.aff-card h3{font:400 25px/1.2 Georgia,serif;margin:0 0 11px}.aff-card-desc{font-size:13px;color:#606f62;line-height:1.7;margin:0 0 18px;flex:1}.aff-chips{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 17px}.aff-chips span{font-size:10px;border:1px solid #dfd4c2;color:#5e705f;padding:6px 8px}.aff-card-actions{display:grid;grid-template-columns:1fr auto;gap:9px}.aff-card-actions a{background:#203a2c;color:#fff;text-decoration:none;padding:12px 11px;font-size:12px;font-weight:650;text-align:center}.aff-card-actions a:hover{background:#385745}.aff-card-actions button{font-size:18px;min-width:46px;cursor:pointer;border:1px solid #cbbf9f;background:#f7f3e7;color:#314c38}.aff-card-actions button[aria-pressed=true]{background:#dcc696}.aff-card-foot{font-size:10px;color:#7a8078;margin-top:12px}.aff-empty{padding:50px;background:#f1eadd;text-align:center}.aff-trust{background:#e6e6df;padding:90px 0}.aff-partners{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin-top:32px}.aff-partners article{background:#fafaf5;border:1px solid #d6dcd4;padding:26px}.aff-partners strong{font:400 24px Georgia,serif}.aff-partners p{font-size:13px;line-height:1.7;color:#5e7061;min-height:92px}.aff-partners a{font-size:12px;color:#28573b}.aff-small{font-size:12px;color:#687969;margin:23px 0 0}.aff-other{background:#273f32;color:#fff;text-align:center;padding:93px 0}.aff-other h2{color:#fff;margin:0 0 20px}.aff-other p:not(.overline){color:#d8e1d6;max-width:650px;margin:0 auto 30px;line-height:1.8}
@media(max-width:940px){.aff-hero-inner{grid-template-columns:1fr}.aff-copy{padding:80px 0 10px}.aff-hero-scene{height:330px}.aff-orbit{width:310px;height:310px}.aff-stage-strap{height:260px;width:95px}.aff-stage-dial{width:170px;height:170px}.aff-heading{grid-template-columns:1fr;gap:8px}.aff-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.aff-partners{grid-template-columns:1fr}.aff-partners p{min-height:0}}
@media(max-width:620px){.aff-hero-inner{gap:0}.aff-copy{padding:66px 0 0}.aff-copy h1{font-size:clamp(48px,11.6vw,68px)}.aff-tiers .wrap{grid-template-columns:1fr}.aff-tier-grid>a{min-height:135px;padding:26px}.aff-selection,.aff-trust,.aff-other{padding:65px 0}.aff-grid{grid-template-columns:1fr}.aff-illustration{height:230px}.aff-tools{display:block}.aff-query{margin-top:14px}.aff-query input{width:100%}.aff-hero-legend{font-size:8px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
.aff-card{box-shadow:0 14px 40px #1b29250a;transition:transform .2s ease,box-shadow .2s ease}.aff-card:hover{transform:translateY(-5px);box-shadow:0 20px 45px #1b292520}.aff-card-actions a:focus-visible,.aff-card-actions button:focus-visible{outline:3px solid #d6b47b;outline-offset:3px}@media(prefers-reduced-motion:reduce){.aff-card{transition:none}.aff-card:hover{transform:none}}

/* Manufacturer packshots: consistent neutral art direction */
.aff-illustration:has(.aff-product-photo){background:#f5f3ed!important;padding:17px;overflow:hidden}
.aff-illustration:has(.aff-product-photo)::before{display:none}
.aff-product-photo{position:relative;z-index:1;display:block;max-width:100%;width:100%;height:100%;object-fit:contain;mix-blend-mode:multiply;filter:drop-shadow(0 9px 9px #24332712);transition:transform .4s ease}
.aff-card:hover .aff-product-photo{transform:scale(1.045)}
.aff-illustration:has(.aff-product-photo) .aff-art-label{z-index:2;background:#173626db;color:#fff;font-size:9px;letter-spacing:.055em;max-width:calc(100% - 16px);padding:6px 9px}
@media(prefers-reduced-motion:reduce){.aff-product-photo{transition:none}.aff-card:hover .aff-product-photo{transform:none}}

/* Real product photography in the hero: preserve correct proportions on Android. */
.am-hero-watch.am-hero-real{display:flex;align-items:center;justify-content:center;overflow:visible}.am-hero-real-photo{display:block;width:100%;height:100%;max-width:100%;max-height:100%;object-fit:contain;filter:drop-shadow(0 22px 22px #0a1a1466)}

/* Removable filters: touch-friendly, compact and visible without opening selects. */
.am-active-filters{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin:0 0 22px}.am-active-filters[hidden]{display:none}.am-filter-chip{appearance:none;border:1px solid #c7bca8;background:#e9e6dc;color:#1d3829;border-radius:100px;min-height:42px;padding:9px 15px;font:650 12px/1.4 system-ui,sans-serif;cursor:pointer;transition:background .18s ease,border-color .18s ease}.am-filter-chip:hover{background:#d9e0d5;border-color:#79977f}.am-filter-chip:focus-visible{outline:3px solid #c7a56c;outline-offset:3px}@media(prefers-reduced-motion:reduce){.am-filter-chip{transition:none}}

/* Shareable catalogue link: clear 44px touch target and safe mobile wrapping. */
.am-share-selection{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:0 0 24px}
.am-share-selection button{min-height:44px;border:1px solid #b7a88d;padding:11px 17px;background:#faf8f2;color:#244431;font:650 12px system-ui,sans-serif;letter-spacing:.025em;cursor:pointer}
.am-share-selection button:hover{background:#e9e6da}
.am-share-selection button:focus-visible{outline:3px solid #c9a668;outline-offset:3px}
.am-share-selection [role="status"]{color:#315942;font:12px/1.6 system-ui,sans-serif;overflow-wrap:anywhere;max-width:100%}
@media(max-width:620px){.am-share-selection button{width:100%;text-align:center}.am-share-selection{align-items:stretch}}

'use strict';
(() => {
 const $=id=>document.getElementById(id);
 const grid=$('affGrid'),tabs=$('affTabs'),search=$('affSearch'),count=$('affResultCount'),savedCount=$('affSavedCount'),empty=$('affEmpty'),sort=$('affSort'),movementSelect=$('affMovement'),brandSelect=$('affBrand'),reset=$('affReset');
 if(!grid||!tabs||!search||!count||!savedCount||!empty)return;
 const levels={essential:'Essentielle',signature:'Signature',prestige:'Prestige'},moves={quartz:'Quartz',automatic:'Automatique','eco-drive':'Solaire'};
 const approvedHosts=['casio.com','swatch.com','citizenwatch.eu','orientwatch.fr','seikowatches.com','tissotwatches.com','hamiltonwatch.com'];
 let data=[],tier='all',query='',order='editorial',movement='all',brand='all',visible=[],saved=new Set(),compare=[];
 const KEY='atelier-montres-multibrand-favorites-v1';
 try{const x=JSON.parse(localStorage.getItem(KEY)||'[]');if(Array.isArray(x))saved=new Set(x.filter(y=>typeof y==='string'&&y.length<80))}catch(_){}
 const make=(tag,cls,txt)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(txt!==undefined)n.textContent=txt;return n;};
 const official=url=>{try{const u=new URL(url);return u.protocol==='https:'&&!u.username&&!u.password&&approvedHosts.some(x=>u.hostname===x||u.hostname.endsWith('.'+x))}catch(_){return false}};
 const valid=p=>p&&p.affiliateUrl===null&&p.merchantLinkStatus==='untracked_official'&&p.photoRights==='not_licensed'&&p.imageMode==='custom_vector_illustration'&&Object.hasOwn(levels,p.tier)&&typeof p.id==='string'&&typeof p.brand==='string'&&typeof p.model==='string'&&typeof p.description==='string'&&official(p.officialUrl);
 const word=p=>[p.brand,p.model,p.title,p.description,p.style,p.tier,p.movement,...(p.highlights||[])].join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const photoSources=p=>{const t=p?.photoReview,files=[];if(t?.localUrl==='./assets/watches/'+p.id+'.webp')files.push(t.localUrl+(typeof t.localSha256==='string'&&/^[a-f0-9]{64}$/.test(t.localSha256)?'?v='+t.localSha256.slice(0,12):''));if(typeof t?.url==='string'&&t.url.startsWith('https://'))files.push(t.url);return files;};
 const detail=id=>'./montre.html?id='+encodeURIComponent(id);
 const compareTray=$('affCompareTray'),compareLabel=$('affCompareLabel'),compareOpen=$('affCompareOpen'),compareClear=$('affCompareClear'),dialog=$('affCompareDialog'),compareBody=$('affCompareBody');
 function updateCompare(){
   compare=compare.filter(id=>data.some(p=>p.id===id));
   if(compareTray)compareTray.hidden=compare.length===0;
   if(compareLabel)compareLabel.textContent=compare.length+' montre'+(compare.length>1?'s':'')+' à comparer (3 max)';
   if(compareOpen)compareOpen.disabled=compare.length<2;
 }
 function card(p){
   const item=make('article','aff-card');
   const art=make('div','aff-illustration');art.dataset.tone=p.tone||'silver';
   const photo=p.photoReview,sources=photoSources(p);
   const vector=()=>{art.replaceChildren();if(window.AtelierWatch)window.AtelierWatch.render(art,p);art.append(make('span','aff-art-label','PHOTO INDISPONIBLE · FICHE FABRICANT'))};
   if(photo?.accuracy==='exact'&&sources.length){
     const img=make('img','aff-product-photo');img.alt=p.brand+' '+p.model+' — photographie authentique';img.loading='lazy';img.decoding='async';img.referrerPolicy='no-referrer';
     let sourceIndex=0;img.onerror=()=>{sourceIndex++;if(sourceIndex<sources.length)img.src=sources[sourceIndex];else vector()};
     art.append(img,make('span','aff-art-label','PHOTOGRAPHIE DU MODÈLE · '+photo.provider.toUpperCase()));
     const expand=make('button','aff-photo-expand');expand.type='button';expand.setAttribute('aria-label','Agrandir la photographie de '+p.brand+' '+p.model);expand.append(make('span','','⤢ Agrandir'));expand.addEventListener('click',()=>window.AtelierPhoto?.open(visible,p.id));art.append(expand);img.src=sources[0];
   }else vector();
   const body=make('div','aff-card-body');
   body.append(make('p','aff-card-brand',p.brand.toUpperCase()),make('h3','',p.model),make('p','am-card-title',p.title||''),make('p','aff-card-desc',p.story||p.description));
   const chips=make('div','aff-chips');chips.append(make('span','',levels[p.tier]),make('span','',moves[p.movement]||'Horlogerie'));body.append(chips);
   const specs=make('div','am-spec-line');for(const h of (p.highlights||[]).slice(0,3))specs.append(make('span','',h));body.append(specs);
   const actions=make('div','aff-card-actions');const link=make('a','','Découvrir la montre ↗');link.href=detail(p.id);
   const like=make('button','',saved.has(p.id)?'♥':'♡');like.type='button';like.setAttribute('aria-pressed',String(saved.has(p.id)));like.setAttribute('aria-label',(saved.has(p.id)?'Retirer des favoris : ':'Ajouter aux favoris : ')+p.model);
   like.addEventListener('click',()=>{saved.has(p.id)?saved.delete(p.id):saved.add(p.id);try{localStorage.setItem(KEY,JSON.stringify([...saved]))}catch(_){}render()});
   actions.append(link,like);body.append(actions);
   const compareWrap=make('div','am-card-footer');
   const maker=make('a','','Photos officielles ↗');maker.href=p.officialUrl;maker.target='_blank';maker.rel='noopener noreferrer nofollow';maker.setAttribute('aria-label','Voir '+p.model+' chez '+p.brand);
   const select=make('label','am-compare-check');const cb=make('input');cb.type='checkbox';cb.checked=compare.includes(p.id);cb.setAttribute('aria-label','Comparer '+p.model);
   cb.addEventListener('change',()=>{if(cb.checked&&!compare.includes(p.id)){if(compare.length>=3){cb.checked=false;return;}compare.push(p.id)}else compare=compare.filter(id=>id!==p.id);updateCompare()});
   select.append(cb,document.createTextNode(' Comparer'));compareWrap.append(maker,select);body.append(compareWrap);
   body.append(make('p','aff-card-foot','Modèle réel · Liens actuellement non rémunérés'));
   item.append(art,body);return item;
 }
 const recentlyKey='atelier-montres-recent-v1';
 function renderRecentlyViewed(){
   const section=$('affRecentlyViewed'),target=$('affRecentlyGrid');
   if(!section||!target)return;
   let ids=[];
   try{
     const previous=JSON.parse(localStorage.getItem(recentlyKey)||'[]');
     if(Array.isArray(previous))ids=[...new Set(previous.filter(id=>typeof id==='string'&&id.length<80))].slice(0,5);
   }catch(_){}
   const models=ids.map(id=>data.find(p=>p.id===id)).filter(Boolean);
   section.hidden=models.length===0;
   const nodes=models.map(p=>{
     const a=make('a','am-recent-card');
     a.href=detail(p.id);a.setAttribute('aria-label','Revoir '+p.brand+' '+p.model);
     const picture=make('span','am-recent-image');
     if(p.photoReview?.localUrl==='./assets/watches/'+p.id+'.webp'){
       const img=make('img');img.src=p.photoReview.localUrl;img.alt='';img.loading='lazy';img.decoding='async';img.width=120;img.height=120;
       img.onerror=()=>{img.remove();picture.append(make('span','am-recent-photo-missing','Photo indisponible'))};
       picture.append(img);
     }else picture.append(make('span','am-recent-photo-missing','Voir le modèle'));
     const label=make('span','am-recent-name');
     label.append(make('small','',p.brand),make('strong','',p.model));
     a.append(picture,label);
     return a;
   });
   target.replaceChildren(...nodes);
 }
 if($('affRecentlyClear'))$('affRecentlyClear').addEventListener('click',()=>{
   try{localStorage.removeItem(recentlyKey)}catch(_){}
   renderRecentlyViewed();
 });
 window.addEventListener('pageshow',()=>{if(data.length)renderRecentlyViewed()});
 function renderActiveFilters(){
   const target=$('affActiveFilters');if(!target)return;
   const active=[];
   if(tier!=='all')active.push(['tier',tier==='favourites'?'Favoris':levels[tier]]);
   if(brand!=='all')active.push(['brand',brand]);
   if(movement!=='all')active.push(['movement',moves[movement]||movement]);
   if(query.trim())active.push(['query','Recherche : '+query.trim()]);
   target.hidden=active.length===0;
   target.replaceChildren(...active.map(([key,label])=>{
     const b=make('button','am-filter-chip',label+' ×');b.type='button';b.setAttribute('aria-label','Supprimer le filtre '+label);
     b.addEventListener('click',()=>{
       if(key==='tier')tier='all';
       if(key==='brand'){brand='all';if(brandSelect)brandSelect.value='all'}
       if(key==='movement'){movement='all';if(movementSelect)movementSelect.value='all'}
       if(key==='query'){query='';search.value=''}
       render();
     });return b;
   }));
 }
 function render(){
   const q=query.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
   visible=data.filter(p=>(tier==='all'||(tier==='favourites'?saved.has(p.id):p.tier===tier))&&(movement==='all'||p.movement===movement)&&(brand==='all'||p.brand===brand)&&word(p).includes(q));
   if(order==='brand')visible=visible.slice().sort((a,b)=>(a.brand+' '+a.model).localeCompare(b.brand+' '+b.model,'fr'));
   if(order==='name')visible=visible.slice().sort((a,b)=>a.model.localeCompare(b.model,'fr'));
   grid.replaceChildren(...visible.map(card));renderActiveFilters();renderRecentlyViewed();empty.hidden=visible.length>0;if(reset)reset.hidden=visible.length>0;
   savedCount.textContent=String([...saved].filter(id=>data.some(p=>p.id===id)).length);
   count.textContent=visible.length+' montre'+(visible.length>1?'s':'')+' sélectionnée'+(visible.length>1?'s':'');
   tabs.querySelectorAll('button[data-tier]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tier===tier)));
   updateCompare();
 }
 tabs.addEventListener('click',e=>{const b=e.target.closest('button[data-tier]');if(!b)return;tier=b.dataset.tier;render()});
 document.querySelectorAll('.am-mobile-nav a').forEach(a=>a.addEventListener('click',()=>{const menu=a.closest('details');if(menu)menu.open=false}));
 search.addEventListener('input',()=>{query=search.value.slice(0,100);render()});
 if(sort)sort.addEventListener('change',()=>{order=sort.value;render()});
 if(movementSelect)movementSelect.addEventListener('change',()=>{movement=movementSelect.value;render()});
 if(brandSelect)brandSelect.addEventListener('change',()=>{brand=brandSelect.value;render()});
 if(reset)reset.addEventListener('click',()=>{tier='all';movement='all';brand='all';query='';order='editorial';search.value='';if(sort)sort.value='editorial';if(movementSelect)movementSelect.value='all';if(brandSelect)brandSelect.value='all';render();search.focus()});
 document.querySelectorAll('a[data-goto-tier]').forEach(a=>a.addEventListener('click',()=>{tier=a.dataset.gotoTier;render()}));
 function comparisonRows(selected){
   return [
     ['Gamme',p=>levels[p.tier]],
     ['Mouvement',p=>p.specs?.movement||moves[p.movement]||'Non confirmé'],
     ['Diamètre',p=>p.specs?.diameter||'À vérifier'],
     ['Verre',p=>p.specs?.glass||'À vérifier'],
     ['Étanchéité',p=>p.specs?.waterResistance||'À vérifier']
   ].map(([label,get])=>{
     const values=selected.map(get);
     return {label,values,different:new Set(values).size>1};
   });
 }
 function compareImage(p,cls){
   const sources=photoSources(p),img=make('img',cls);
   img.alt='Photographie '+p.brand+' '+p.model;img.decoding='async';img.loading='lazy';img.referrerPolicy='no-referrer';
   if(sources.length){let pos=0;img.onerror=()=>{pos++;if(pos<sources.length)img.src=sources[pos];else img.remove()};img.src=sources[0]}
   return sources.length?img:null;
 }
 function showComparison(){
   if(!dialog||!compareBody||compare.length<2)return;
   const selected=compare.map(id=>data.find(p=>p.id===id)).filter(Boolean);
   if(selected.length<2)return;
   const rows=comparisonRows(selected);
   const table=make('table','am-compare-table'),head=make('thead'),tr=make('tr');
   tr.append(make('th','am-compare-criterion','Critère'));
   for(const p of selected){
     const th=make('th','am-compare-head');
     const image=compareImage(p,'am-compare-thumb');if(image)th.append(image);
     th.append(make('span','am-compare-name',p.brand+' '+p.model));tr.append(th);
   }
   head.append(tr);table.append(head);
   const tbody=make('tbody');
   for(const item of rows){
     const row=make('tr');row.append(make('th','am-compare-criterion',item.label));
     item.values.forEach(value=>row.append(make('td',item.different?'am-compare-different':'',value)));
     tbody.append(row);
   }
   const row=make('tr');row.append(make('th','am-compare-criterion','Fiche'));
   for(const p of selected){const td=make('td'),a=make('a','','Découvrir ↗');a.href=detail(p.id);td.append(a);row.append(td)}
   tbody.append(row);table.append(tbody);
   const mobile=make('div','am-compare-mobile');
   const guide=make('p','am-compare-mobile-hint','Faites glisser pour consulter chaque montre.');
   const track=make('div','am-compare-mobile-track');track.tabIndex=0;track.setAttribute('role','region');track.setAttribute('aria-label','Comparatif des montres, balayage horizontal');
   const slides=selected.map((p,index)=>{
     const card=make('article','am-compare-mobile-card');
     const header=make('div','am-compare-mobile-product');
     header.append(make('span','am-compare-mobile-counter',(index+1)+' / '+selected.length));
     const photo=compareImage(p,'am-compare-mobile-photo');if(photo)header.append(photo);
     header.append(make('h3','',p.brand+' '+p.model));card.append(header);
     const dl=make('dl','am-compare-mobile-specs');
     for(const item of rows){
       const line=make('div',item.different?'am-compare-mobile-diff':'');
       line.append(make('dt','',item.label),make('dd','',item.values[index]));dl.append(line);
     }
     card.append(dl);
     const link=make('a','am-compare-mobile-detail','Découvrir la fiche →');link.href=detail(p.id);card.append(link);
     return card;
   });
   track.append(...slides);
   const nav=make('div','am-compare-mobile-nav');
   const prev=make('button','','← Précédente'),next=make('button','','Suivante →'),position=make('span','am-compare-mobile-position','1 / '+slides.length);
   prev.type='button';next.type='button';prev.disabled=true;
   const select=i=>{
     const n=Math.min(slides.length-1,Math.max(0,i));
     track.scrollTo({left:slides[n].offsetLeft-slides[0].offsetLeft,behavior:'smooth'});
     position.textContent=(n+1)+' / '+slides.length;prev.disabled=n===0;next.disabled=n===slides.length-1;
   };
   prev.addEventListener('click',()=>select(Math.max(0,Math.round(track.scrollLeft/Math.max(1,slides[1]?.offsetLeft-slides[0].offsetLeft))-1)));
   next.addEventListener('click',()=>select(Math.min(slides.length-1,Math.round(track.scrollLeft/Math.max(1,slides[1]?.offsetLeft-slides[0].offsetLeft))+1)));
   track.addEventListener('scroll',()=>{
     const step=slides[1]?.offsetLeft-slides[0].offsetLeft||track.clientWidth;
     const i=Math.min(slides.length-1,Math.max(0,Math.round(track.scrollLeft/Math.max(1,step))));
     position.textContent=(i+1)+' / '+slides.length;prev.disabled=i===0;next.disabled=i===slides.length-1;
   },{passive:true});
   nav.append(prev,position,next);mobile.append(guide,track,nav);
   compareBody.replaceChildren(make('p','am-compare-diff-note','Les caractéristiques différentes sont mises en évidence. Aucune donnée de prix ou de stock n’est estimée.'),table,mobile);
   if(typeof dialog.showModal==='function'&&!dialog.open)dialog.showModal();
 }
 if(compareOpen)compareOpen.addEventListener('click',showComparison);
 if(compareClear)compareClear.addEventListener('click',()=>{compare=[];render()});
