 if(dialog)dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
 fetch('./selection-affiliation.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('data');return r.json()}).then(x=>{
